const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false')}});const form=document.querySelector('#cerere');if(form){const part=new URLSearchParams(location.search).get('part');if(part)form.querySelector('[name=piesa]').value=part.slice(0,1500);const t0=Date.now();const status=document.querySelector('#form-status');const clean=v=>String(v||'Nespecificat').normalize('NFKC').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g,'').trim();const waText=()=>{const data=new FormData(form);return['Bună ziua! Vă contactez de pe fordcargo.ro. Doresc o ofertă pentru piese de camion Ford.',...[['prenume','Prenume'],['nume','Nume'],['telefon','Telefon'],['email','E-mail'],['vin','VIN'],['piesa','Piesa']].map(([k,l])=>l+': '+clean(data.get(k)))].join('\n')};const waUrl=()=>'https://wa.me/40733357357?text='+encodeURIComponent(waText());form.querySelector('.wa-send')?.addEventListener('click',()=>{if(!form.reportValidity())return;location.href=waUrl()});form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;if(form.elements.website?.value)return;const btn=form.querySelector('[type=submit]');btn.disabled=true;status.className='';status.textContent='Se trimite cererea…';const data=Object.fromEntries(new FormData(form));data.consent=!!form.elements.consent?.checked;data.t=t0;const fail=msg=>{status.className='error';status.textContent=msg+' ';const a=document.createElement('a');a.href=waUrl();a.className='inline';a.textContent='Trimite cererea pe WhatsApp';status.append(a,' sau sună la +40 733 357 357.')};try{const r=await fetch('/trimite-cerere.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json().catch(()=>({}));if(r.ok&&j.ok){form.reset();status.className='ok';status.textContent='Mulțumim! Cererea a fost trimisă către echipa EKS LKW. Te contactăm de obicei în aceeași zi lucrătoare.'}else if(j.error==='limit'){fail('Ai trimis deja mai multe cereri. Încearcă din nou peste 15 minute.')}else if(j.error==='timing'){status.className='error';status.textContent='Verifică datele și apasă din nou „Trimite cererea”.'}else if(j.error==='phone'||j.error==='email'||j.error==='required'){status.className='error';status.textContent='Verifică numărul de telefon, adresa de e-mail și câmpurile obligatorii.'}else{fail('Cererea nu a putut fi trimisă automat.')}}catch(e){fail('Cererea nu a putut fi trimisă automat.')}finally{btn.disabled=false}});form.querySelector('[type=submit]').disabled=false;}
document.querySelectorAll('.photo-motion-toggle').forEach(button=>button.addEventListener('click',()=>{const paused=button.closest('.animated-photo').classList.toggle('paused');button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'Pornește mișcarea fotografiei':'Oprește mișcarea fotografiei');button.firstElementChild.textContent=paused?'▷':'Ⅱ'}));

document.querySelectorAll('.icon-motion-toggle').forEach(button=>button.addEventListener('click',()=>{const paused=button.closest('.icon-carousel').classList.toggle('paused');button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'Reia derularea pieselor':'Oprește derularea pieselor');button.firstElementChild.textContent=paused?'▷':'Ⅱ'}));

/* buton „sus” — apare după ce pagina este derulată */
(function(){
  var en=document.documentElement.lang==='en';
  var b=document.createElement('button');
  b.type='button';b.className='to-top';b.setAttribute('aria-label',en?'Back to top':'Înapoi sus');b.title=en?'Back to top':'Înapoi sus';
  b.innerHTML='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M12 5l-7 7 1.4 1.4L11 8.8V20h2V8.8l4.6 4.6L19 12z" fill="currentColor"/></svg>';
  b.addEventListener('click',function(){var r=window.matchMedia('(prefers-reduced-motion: reduce)').matches;window.scrollTo({top:0,behavior:r?'auto':'smooth'});});
  document.body.appendChild(b);
  var on=false;function chk(){var v=window.scrollY>600;if(v!==on){on=v;b.classList.toggle('show',v);}}
  window.addEventListener('scroll',chk,{passive:true});chk();
})();
